/**
 * Helper for visualizing the spatial grid used by particle simulations.
 *
 * @class SpatialGridHelper
 * @short Helper that visualizes particle spatial grid cells and optionally labels cell IDs.
 * @category Simulation
 * @tags WebGPU
 *
 * @param {Object} simulation - The simulation object (SPH, Boids) to which the helper is attached.
 * @param {boolean} [showTexts=true] - Whether to show cell IDs as text.
 *
 * @example
  * ```js
 * import { SPH, SpatialGridHelper } from '@three-blocks/core';
 * import * as THREE from 'three/webgpu';
 *
 * // Create SPH simulation with spatial grid enabled
 * const sph = new SPH({
 *   count: 4096,
 *   is3D: true,
 *   domainDimensions: new THREE.Vector3(20, 20, 20),
 *   h: 1.0,
 *   useSpatialGrid: true,
 *   debug: true
 * });
 *
 * // Create and attach grid helper for visualization
 * const gridHelper = new SpatialGridHelper(sph, true);
 * scene.add(gridHelper);
 *
 * // Optional: Update helper when domain changes
 * sph.setDomainFromObject(mesh);
 * gridHelper.init(); // Rebuild grid visualization
 *
 * // Clean up
 * gridHelper.dispose();
 * sph.dispose();
 * ```
 */
export class SpatialGridHelper {
    constructor(simulation: any, showTexts?: boolean);
    simulation: any;
    _showTexts: boolean;
    _helper: any;
    atlasNumber: {
        map: any;
        dimensions: {
            width: number;
            height: number;
            cellWidth: number;
            cellHeight: number;
            numbersPerRow: number;
            totalRows: number;
        };
    };
    init(): void;
    showTexts(): void;
    _helperText: any;
    dispose(): void;
}
